/* Shared order management, vendor shipments and printable invoices. */
(function(){
 'use strict';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>'PKR '+Number(n||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
 const date=s=>new Date(s).toLocaleDateString('en-GB',{timeZone:'Asia/Karachi',day:'2-digit',month:'short',year:'numeric'});
 const stages=['placed','confirmed','processing','shipped','delivered'];
 const stageName=s=>({placed:'Pending',confirmed:'Accepted',processing:'Processing',shipped:'Dispatched',delivered:'Delivered',cancelled:'Cancelled',returned:'Returned'})[s]||s;
 const imageUrl=s=>/^(https:\/\/[^\s]+|\/[a-z0-9][^\s]*)$/i.test(s||'')?s:'';
 const pill=(state,label)=>`<span class="fulfillment-status ${state}"><span aria-hidden="true">${state==='confirmed'?'✓':state==='pending'?'◷':'×'}</span>${esc(label)}</span>`;
 const paymentPill=f=>pill(f.payment_state==='paid'?'confirmed':f.payment_state==='refunded'?'missing':'pending',({paid:'Paid',partial:'Part paid',unpaid:'Unpaid',refund_due:'Refund pending',refunded:'Refunded'})[f.payment_state]||'Unpaid');
 function statuses(o){const f=o.funding||{};return `<div class="fulfillment-statuses"><div><small>Hold / Advance</small>${pill(f.state||'missing',f.ready?f.method:f.state==='pending'?'Awaiting confirmation':'Not confirmed')}</div><div><small>Payment</small>${paymentPill(f)}</div><div><small>Delivery</small>${pill(o.status==='delivered'?'confirmed':['cancelled','returned'].includes(o.status)?'missing':'pending',stageName(o.status))}</div></div>`}
 function invoiceItems(s){return (s.items||[]).flatMap(i=>i.bundle?.items?.length?i.bundle.items.map(p=>({name:p.name,sku:p.sku,image_url:p.image_url,quantity:Number(p.quantity)*Number(i.quantity),unit_price:p.price_pkr,bundle:i.name})): [i])}
 function invoice(o,s=null){
  const shipments=s?[s]:o.shipments||[],items=shipments.flatMap(invoiceItems),gross=shipments.reduce((n,v)=>n+Number(v.gross_pkr),0),discount=shipments.reduce((n,v)=>n+Number(v.discount_pkr),0),shipping=shipments.reduce((n,v)=>n+Number(v.delivery_pkr),0),total=s?Number(s.total_pkr):Number(o.total_pkr),paid=s?Number(s.paid_pkr):Number(o.funding.paid_pkr),due=['cancelled','returned'].includes(o.status)?0:Math.max(0,Math.round((total-paid)*100)/100),code=s?.shipment_code||o.order_code,number=s?.invoice_number||'INV-'+o.order_code;
  return `<article class="mio-order-invoice"><header class="invoice-brand-row"><div><img src="/market-is-online-logo-header.svg" alt="Market is Online"><p>E-Commerce & Network Marketing Platform</p></div><div><h1>ORDER INVOICE</h1><span>${s?'Vendor shipment':'Order summary'}</span></div></header><div class="invoice-accent"></div><div class="invoice-metadata"><dl><dt>Order Number</dt><dd>${esc(o.order_code)}</dd><dt>Invoice Number</dt><dd>${esc(number)}</dd><dt>Order Date</dt><dd>${date(o.created_at)}</dd>${s?'<dt>Shipment</dt><dd>'+esc(s.shipment_code)+'</dd>':''}</dl><dl><dt>Payment Method</dt><dd>${o.funding.payment_state==='paid'?'Paid in full':Number(o.shopping_points_used)>0?'Shopping Points + COD':'Cash on Delivery'}</dd><dt>Payment Status</dt><dd>${paymentPill(o.funding)}</dd><dt>Order Status</dt><dd>${esc(stageName(o.status))}</dd><dt>Delivery Status</dt><dd>${esc(stageName(s?.status||o.status))}</dd></dl></div><div class="invoice-addresses"><section><h2>Billing Address</h2><div><strong>${esc(o.shipping_name)}</strong><p>${esc(o.shipping_address)}</p><p>${esc(o.shipping_city)}</p><p>${esc(o.shipping_phone)}</p></div></section><section><h2>Shipping Address</h2><div><strong>${esc(o.shipping_name)}</strong><p>${esc(o.shipping_address)}</p><p>${esc(o.shipping_city)}</p><p>${esc(o.shipping_phone)}</p></div></section></div><div class="invoice-seller"><strong>Seller Information</strong><div>${shipments.map(v=>`<b>${esc(v.vendor_snapshot.name)}</b><span>${esc(v.vendor_snapshot.country||'Pakistan')}${v.vendor_snapshot.phone?' · '+esc(v.vendor_snapshot.phone):''}</span>`).join('')}</div></div><div class="invoice-table-wrap"><table class="invoice-product-table"><thead><tr><th>#</th><th>Product</th><th>SKU</th><th>Qty</th><th>Unit Price (PKR)</th><th>Total (PKR)</th></tr></thead><tbody>${items.map((i,index)=>`<tr><td>${index+1}</td><td><div class="invoice-product">${imageUrl(i.image_url)?`<img src="${esc(imageUrl(i.image_url))}" alt="">`:''}<div><strong>${esc(i.name)}</strong>${i.bundle?'<small>'+esc(i.bundle)+'</small>':''}</div></div></td><td>${esc(i.sku||'—')}</td><td>${Number(i.quantity)}</td><td>${money(i.unit_price)}</td><td>${money(Number(i.unit_price)*Number(i.quantity))}</td></tr>`).join('')}</tbody></table></div><div class="invoice-bottom"><p class="invoice-reward-note">PPV eligibility is determined after delivery and confirmed payment. Sponsor/MIO holds are security and do not reduce the amount payable.</p><dl class="invoice-amounts"><dt>Subtotal</dt><dd>${money(gross)}</dd><dt>Discount</dt><dd>− ${money(discount)}</dd><dt>Shipping</dt><dd>${money(shipping)}</dd><dt class="invoice-grand">GRAND TOTAL</dt><dd class="invoice-grand">${money(total)}</dd><dt>Payments received</dt><dd>${money(paid)}</dd>${o.funding.payment_state==='refund_due'?'<dt>Refund pending</dt><dd>'+money(paid)+'</dd>':''}<dt><strong>Remaining to collect</strong></dt><dd><strong>${money(due)}</strong></dd></dl></div><footer class="invoice-codes"><div class="invoice-qr" data-invoice-qr="${esc(o.id)}"><small>Open secure order details</small></div><div><svg data-invoice-barcode="${esc(code)}" role="img" aria-label="Barcode ${esc(code)}"></svg><small>${esc(code)}</small></div><img src="/market-is-online-logo-header.svg" alt="Market is Online"></footer><div class="invoice-accent"></div></article>`;
 }
 function decorateInvoices(root){root.querySelectorAll('[data-invoice-qr]').forEach(el=>{const qr=window.qrcode(0,'M');qr.addData(location.origin+location.pathname+'#order/'+el.dataset.invoiceQr);qr.make();el.insertAdjacentHTML('afterbegin',qr.createSvgTag({cellSize:3,margin:12,scalable:true,alt:'Secure order QR code'}));});root.querySelectorAll('[data-invoice-barcode]').forEach(el=>window.JsBarcode(el,el.dataset.invoiceBarcode,{format:'CODE128',width:2,height:54,margin:12,displayValue:false}));}
 function create({db,getSession,toast,submit,afterChange}){
  let selected=null,version=0,dialog=null,receipt=null,opener=null;
  const rows=new Map();
  async function rpc(name,args){const {data,error}=await db.rpc(name,args);if(error)throw error;return data}
  function shipment(o,s){const closed=['cancelled','returned'].includes(o.status),next=stages[stages.indexOf(s.status)+1],due=closed?0:Math.max(0,Number(s.total_pkr)-Number(s.paid_pkr));return `<section class="vendor-shipment"><header><div><small>${esc(s.shipment_code)}</small><h3>${esc(s.vendor_snapshot.name)}</h3></div>${pill(s.status==='delivered'?'confirmed':closed?'missing':'pending',stageName(s.status))}</header><ul>${invoiceItems(s).map(i=>`<li><span>${esc(i.name)} <small>× ${Number(i.quantity)}</small></span><b>${money(Number(i.unit_price)*Number(i.quantity))}</b></li>`).join('')}</ul><dl><dt>Product discount</dt><dd>− ${money(s.discount_pkr)}</dd><dt>Vendor delivery</dt><dd>${money(s.delivery_pkr)}</dd><dt>Shipment total</dt><dd>${money(s.total_pkr)}</dd><dt>Payment allocated</dt><dd>${money(s.paid_pkr)}</dd><dt>Remaining COD</dt><dd>${money(due)}</dd></dl><div class="shipment-actions"><button type="button" class="btn small" data-invoice-order="${o.id}" data-invoice-shipment="${s.id}">View invoice</button>${o.can_manage&&next&&!closed?`<button type="button" class="btn primary small" data-advance-shipment="${s.id}" data-next-stage="${next}" ${o.funding.ready?'':'disabled'}>${next==='confirmed'?'Accept shipment':'Mark '+stageName(next)}</button>`:''}</div></section>`}
  function content(o){const closed=['cancelled','returned'].includes(o.status),next=stages[stages.indexOf(o.status)+1];return `<div class="order-detail-intro"><small>${date(o.created_at)}</small><h2>${esc(o.order_code)}</h2><p>${esc(o.shipping_name)} · ${esc(o.shipping_city)}</p></div>${statuses(o)}<div class="order-detail-totals"><div><span>Order total</span><b>${money(o.total_pkr)}</b></div><div><span>Received</span><b>${money(o.funding.paid_pkr)}</b></div><div><span>Remaining COD</span><b>${money(o.funding.due_pkr)}</b></div></div>${o.funding.refund_due_pkr>0?'<p class="order-funding-notice">Refund pending: '+money(o.funding.refund_due_pkr)+'. No further payment is due.</p>':''}<div class="order-reward-summary"><span>PPV on hold <b>${Number(o.rewards_credited_at||closed?0:o.reward_ppv_total||0).toFixed(4)}</b></span><span>PPV credited <b>${Number(o.ppv_generated||0).toFixed(4)}</b></span></div>${!closed&&!o.funding.ready?'<p class="order-funding-notice">Acceptance is locked until the required MIO hold or advance payment is confirmed.</p>':''}<div class="order-primary-actions"><button type="button" class="btn" data-invoice-order="${o.id}">Order invoice</button><button type="button" class="btn" data-invoice-order="${o.id}" data-invoice-all>All vendor invoices</button>${o.can_manage&&!closed&&next?`<button type="button" class="btn primary" data-advance-order="${o.id}" data-next-stage="${next}" ${o.funding.ready?'':'disabled'}>${next==='confirmed'?'Accept order':'Mark all '+stageName(next)}</button>`:''}${o.can_manage&&o.status==='delivered'&&o.payment_status!=='confirmed'?`<button type="button" class="btn primary" data-confirm-cod="${o.id}">Confirm remaining payment · ${money(o.funding.due_pkr)}</button>`:''}${o.can_manage&&o.payment_status==='unconfirmed'&&['placed','confirmed','processing'].includes(o.status)&&o.shipments.every(s=>['placed','confirmed','processing'].includes(s.status))?`<button type="button" class="btn" data-cancel-order="${o.id}">Cancel order & restore stock</button>`:''}</div><h3 class="vendor-shipments-heading">${o.shipments.length} vendor ${o.shipments.length===1?'shipment':'shipments'}</h3><p class="vendor-shipments-note">Delivery is charged once per vendor. Each shipment has its own invoice and delivery progress.</p><div class="vendor-shipments">${o.shipments.map(s=>shipment(o,s)).join('')}</div><section class="order-delivery-address"><h3>Delivery address</h3><p>${esc(o.shipping_name)} · ${esc(o.shipping_phone)}</p><p>${esc(o.shipping_address)}, ${esc(o.shipping_city)}</p></section>`}
  function adminRow(o,f){return `<article class="review-card admin-compact-record admin-order-record" data-admin-order data-order-id="${o.id}" data-order-status="${esc(o.status)}" data-payment-status="${esc(o.payment_status)}"><div class="admin-compact-summary admin-order-summary"><span class="admin-order-code"><small>${date(o.created_at)}</small><strong><a href="#order/${o.id}">${esc(o.order_code)}</a></strong></span><span class="admin-order-customer"><strong>${esc(o.shipping_name||'—')}</strong><small>${esc(o.shipping_city||'—')}</small></span><span data-label="Hold / Advance">${pill(f.state||'missing',f.ready?f.method:f.state==='pending'?'Pending':'Not confirmed')}</span><span data-label="Payment">${paymentPill(f)}</span><span data-label="Delivery">${pill(o.status==='delivered'?'confirmed':['cancelled','returned'].includes(o.status)?'missing':'pending',stageName(o.status))}</span><b>${money(o.total_pkr)}</b><button type="button" class="btn small" data-manage-order="${o.id}">Manage</button></div></article>`}
  async function renderAdmin(orders,target){const uid=getSession()?.user.id;const data=orders.length?await rpc('admin_order_funding_states',{p_orders:orders.map(o=>o.id)}):{};if(getSession()?.user.id!==uid)return;rows.clear();orders.forEach(o=>rows.set(o.id,o));target.innerHTML=orders.length?'<div class="admin-list-header orders"><span>Order / Date</span><span>Customer / City</span><span>Hold / Advance</span><span>Payment</span><span>Delivery</span><span>Total</span><span>Action</span></div>'+orders.map(o=>adminRow(o,data?.[o.id]||{})).join(''):'<p>No orders yet.</p>';}
  function close(){version++;dialog?.close();selected=null;opener?.focus?.();}
  async function load(id,target){const uid=getSession()?.user.id,turn=++version;const o=await rpc('order_fulfillment_details',{p_order:id});if(uid!==getSession()?.user.id||turn!==version)return null;if(!o)throw Error('This order is unavailable for your account.');if(target){target.innerHTML=content(o);target.dataset.fulfillmentOrder=id;}return o;}
  async function open(id){if(!dialog){dialog=document.createElement('dialog');dialog.className='order-management-dialog';dialog.setAttribute('aria-label','Order details');dialog.innerHTML='<div class="order-dialog-header"><strong>Order details</strong><button type="button" class="btn small" data-close-order-dialog aria-label="Close order details">×</button></div><div class="order-management-body"></div><p class="order-action-status" role="status"></p>';document.body.append(dialog);dialog.addEventListener('cancel',()=>{version++;selected=null;opener?.focus?.()})}opener=document.activeElement;selected=id;dialog.querySelector('.order-management-body').innerHTML='<p role="status">Loading order…</p>';dialog.querySelector('.order-action-status').textContent='';if(!dialog.open)dialog.showModal();try{await load(id,dialog.querySelector('.order-management-body'))}catch(e){dialog.querySelector('.order-management-body').textContent=e.message;}}
  async function refreshOrder(id){const body=dialog?.open&&selected===id?dialog.querySelector('.order-management-body'):document.querySelector('[data-fulfillment-order="'+id+'"]'),scroll=body?.scrollTop||0;const o=await load(id,body);if(!o)return;if(body)body.scrollTop=scroll;const row=document.querySelector('[data-admin-order][data-order-id="'+id+'"]');if(row){const hidden=row.hidden,display=row.style.display;row.outerHTML=adminRow({...rows.get(id),...o},o.funding);const replacement=document.querySelector('[data-admin-order][data-order-id="'+id+'"]');replacement.hidden=hidden;replacement.style.display=display;}afterChange?.(o);}
  async function showInvoice(id,shipmentId=null,all=false){const o=await load(id);if(!o)return;if(!receipt){receipt=document.createElement('dialog');receipt.className='invoice-dialog';receipt.setAttribute('aria-label','Order invoice');document.body.append(receipt)}receipt.innerHTML='<div class="invoice-dialog-toolbar"><strong>Invoice & delivery slips</strong><div><button type="button" class="btn primary" data-print-invoices>Print / Save PDF</button><button type="button" class="btn" data-close-invoices>Close</button></div></div><div class="invoice-pages">'+(all?o.shipments.map(s=>invoice(o,s)).join(''):invoice(o,shipmentId?o.shipments.find(s=>s.id===shipmentId):null))+'</div>';decorateInvoices(receipt);if(!receipt.open)receipt.showModal();}
  function print(){const frame=document.createElement('iframe');frame.className='invoice-print-frame';frame.title='Printable order invoices';document.body.append(frame);const doc=frame.contentDocument;let printed=false;frame.onload=async()=>{if(printed)return;printed=true;await Promise.all([...doc.images].map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.onload=resolve;img.onerror=resolve})));if(doc.fonts?.ready)await doc.fonts.ready;frame.contentWindow.onafterprint=()=>frame.remove();frame.contentWindow.focus();frame.contentWindow.print();};doc.open();doc.write('<!doctype html><html><head><meta charset="utf-8"><title>Market is Online · Invoice</title><link rel="stylesheet" href="'+location.origin+'/order-fulfillment.css?v=20261112-vendor-orders"></head><body class="invoice-print-document">'+receipt.querySelector('.invoice-pages').innerHTML+'</body></html>');doc.close();}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-manage-order],[data-order-shipments],[data-close-order-dialog],[data-invoice-order],[data-close-invoices],[data-print-invoices],[data-advance-shipment],[data-advance-order],[data-confirm-cod],[data-cancel-order]');if(!b)return;if(b.hasAttribute('data-close-order-dialog'))return close();if(b.hasAttribute('data-close-invoices'))return receipt.close();if(b.hasAttribute('data-print-invoices'))return print();submit({querySelector:()=>b},async()=>{if(b.dataset.manageOrder||b.dataset.orderShipments)return open(b.dataset.manageOrder||b.dataset.orderShipments);if(b.dataset.invoiceOrder)return showInvoice(b.dataset.invoiceOrder,b.dataset.invoiceShipment,b.hasAttribute('data-invoice-all'));const id=selected||b.closest('[data-fulfillment-order]')?.dataset.fulfillmentOrder;try{if(b.dataset.advanceShipment)await rpc('advance_vendor_shipment',{p_shipment:b.dataset.advanceShipment,p_status:b.dataset.nextStage});else if(b.dataset.advanceOrder)await rpc('advance_order_status',{p_order_id:b.dataset.advanceOrder,p_status:b.dataset.nextStage});else if(b.dataset.confirmCod)await rpc('admin_confirm_order_payment',{p_order_id:b.dataset.confirmCod});else if(b.dataset.cancelOrder)await rpc('cancel_unpaid_order',{p_order_id:b.dataset.cancelOrder});await refreshOrder(id);if(dialog?.open)dialog.querySelector('.order-action-status').textContent='Order updated successfully.';toast('Order updated');}catch(error){if(dialog?.open)dialog.querySelector('.order-action-status').textContent=error.message;throw error;}});});
  function clear(){version++;selected=null;rows.clear();dialog?.close();dialog?.remove();receipt?.close();receipt?.remove();dialog=null;receipt=null;}
  return {open,renderAdmin,renderOrder:async(id,target)=>{target.innerHTML='<p role="status">Loading order…</p>';try{await load(id,target)}catch(e){target.textContent=e.message}},showInvoice,refreshOrder,clear};
 }
 window.MioFulfillment={create,invoice,decorateInvoices,statuses,invoiceItems};
})();
